import{z as o,x as i,o as t,c as d,q as B,j as r,D as s,d as e,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SMT","description":"","frontmatter":{"title":"SMT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smt.md","filePath":"cs/smt.md","lastUpdated":1791063341000}'),p={name:"cs/smt.md"};function m(c,a,S,h,T,C){const A=i("Mermaid");return t(),d("div",null,[a[2]||(a[2]=B('<h1 id="smt" tabindex="-1">SMT <a class="header-anchor" href="#smt" aria-label="Permalink to &quot;SMT&quot;">​</a></h1><div class="epigraph"><p>一条流水线的空档，另一条硬件线程的就绪指令可以填；保留站和 cache 变成共享，单线程 IPC 往往略降。</p><footer>—— 据 Tullsen, Eggers and Levy, Simultaneous Multithreading: Maximizing On-Chip Parallelism, ISCA 1995；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/store-buffer">上一课</a>让访存队列托住未提交写。<a href="/cs/ipc-util">IPC 与利用率</a>写明实测 IPC 常远小于宽度：相关、缺失、误预测造成空槽。本课不重讲绕过。缺口是同时多线程（SMT）：同一核上多个逻辑处理器共享取指/发射/执行，每拍可从两条以上线程各取指令，用别的线程的 ILP 填本线程的停顿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单线程在 load 缺失时，ROB 头堵住，后面即使有独立 ALU 也很快耗尽窗口。再加宽超标量，窗口仍是<strong>同一条依赖链</strong>。缺口不是 SIMD（那是下一课的数据级），而是<strong>再取一条不相关的指令流</strong>：它有自己的 PC、寄存器重命名表、ROB 段或线程 ID 标签。</p><p>Tullsen 等人把同一拍发射来自多线程的指令叫做 SMT，以别于粗粒度切换（一缺失才换线程）。</p><p><span class="marginnote">直觉类比：粗粒度切换像柜台只服务一人、这人去取货就整队停摆，停顿攒够了才换下一人；SMT 像两个队列共用一个叫号口，每一拍都能从任一队列叫下一位。前者换线程要清流水线、损失几十拍，后者从不切换、只是共享取指与发射口。</span></p><p><span class="marginnote">操作系统看见的是多个 CPU。架构状态（寄存器、控制寄存器、ASID）每线程一份；L1 与执行单元共享。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每线程：PC、寄存器映射、部分 ROB。共享：保留站、ALU、cache、MSHR、store 缓冲（项上打线程号）。发射选择：轮转、或优先未停顿线程。冲刷只杀该线程的投机状态。</p>',10)),(t(),r(n,null,{default:s(()=>[l(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E7%BA%BF%E7%A8%8B%200%20%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20ISS%5B%22%E5%85%B1%E4%BA%AB%E5%8F%91%E5%B0%84%E5%8F%A3%22%5D%0A%20%20T1%5B%22%E7%BA%BF%E7%A8%8B%201%20%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20ISS%0A%20%20ISS%20--%3E%20EX%5B%22%E5%85%B1%E4%BA%AB%E6%89%A7%E8%A1%8C%E5%8D%95%E5%85%83%22%5D%0A%20%20EX%20--%3E%20C0%5B%22%E6%8F%90%E4%BA%A4%E5%88%B0%E5%90%84%E8%87%AA%20ROB%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"存储缓冲查找必须带线程号，否则会把另一线程的 store 转发给自己。TLB 用各自 ASID，上一课已经允许两项共存。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("核级吞吐（两线程 IPC 之和）上升；单线程延迟可能变差，因为带宽被抢。"),E("a",{href:"/cs/cpi-amdahl"},"阿姆达尔"),e("对「只有一条线程」的程序：SMT 几乎不帮，还可能因 cache 污染变慢。适合混合：一条算、一条等内存。")],-1)),(t(),r(n,null,{default:s(()=>[l(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E7%BA%BF%E7%A8%8B%20A%20%E9%81%87%20load%20%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20B%5B%22A%20%E7%9A%84%E5%8F%91%E5%B0%84%E6%A7%BD%E7%A9%BA%E5%87%BA%22%5D%0A%20%20B%20--%3E%20C%7B%22%E5%90%8C%E4%B8%80%E6%8B%8D%E6%9C%89%E5%88%AB%E7%9A%84%E7%BA%BF%E7%A8%8B%E5%B0%B1%E7%BB%AA%E5%90%97%3F%22%7D%0A%20%20C%20--%20%22SMT%3A%20%E6%9C%89%22%20--%3E%20D%5B%22%E5%90%8C%E6%8B%8D%E5%8F%96%E7%BA%BF%E7%A8%8B%20B%20%E7%9A%84%E6%8C%87%E4%BB%A4%E5%A1%AB%E6%A7%BD%22%5D%0A%20%20C%20--%20%22%E7%B2%97%E7%B2%92%E5%BA%A6%3A%20%E6%89%8D%E6%8D%A2%22%20--%3E%20E%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E7%A9%BA%E8%BD%AC%E6%88%96%E6%B8%85%E7%A9%BA%E6%8D%A2%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20D%20--%3E%20F%5B%22%E6%A0%B8%E7%BA%A7%E5%90%9E%E5%90%90%E5%8D%87%20%E5%8D%95%E7%BA%BF%E7%A8%8B%E5%BB%B6%E8%BF%9F%E5%8F%98%E5%B7%AE%22%5D%0A%20%20E%20--%3E%20F%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">数字实例：一台 4 宽机器单线程实测 IPC 往往只有 1.5 上下——4 个发射槽里空着 2 个半。SMT 让另一条线程把空槽填掉一部分，核级 IPC 之和可能爬到 2.5；但两条线程分摊 cache 与发射带宽，各自的单线程 IPC 也可能从 1.5 掉到 1.2 附近。吞吐是零和之外多出来的空槽，不是白来的性能。</span></p><p>安全与 QoS：侧信道可以共享 cache 当信道，本栏不展开；操作系统可关 SMT。本课只钉性能机制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 GPU 的 SIMT 调度，不把超线程商标当正文。多核是「复制整核 + 共享 LLC」，与 SMT「复制架构状态、共享执行」不同轴；后课才走多核。SIMD 用一条指令打一条向量，也不靠第二套 PC。</p><p><span class="marginnote">常见误区：把 SMT 当成「凭空多一个核」。执行单元并没有复制——两条线程抢的是同一套 ALU、同一块 cache；超线程不是核数翻倍，而是把本来就空着的发射槽变现。对只有一条活跃线程的程序，SMT 帮不上忙，还可能因 cache 污染变慢。</span></p><p>后课默认：空档可用另一硬件线程填。规则排列的同构运算，下一课用 SIMD 收指令数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMT：多套架构状态共享流水线，用别的线程填停顿。</li><li>队列与缓冲必须打线程号；单线程 IPC 可能下降。</li><li>数据级并行（SIMD）是另一轴，下一课。</li><li>出处：Tullsen, Eggers and Levy, <em>ISCA</em>, 1995；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const P=o(p,[["render",m]]);export{u as __pageData,P as default};
